import React from "react";
import { useCart, CartProvider } from "react-use-cart";

function Cart() {
  const {
    updateItemQuantity,
    removeItem,
    totalItems,
    totalUniqueItems,
  } = useCart();

  return (
    <div>
      Cart
    </div>
  );
}

function AllCart() {
  return (
    <CartProvider>
      <Cart />
    </CartProvider>
  );
}

export default AllCart;
